// Drives the real greet binary as a user would and asserts observable output.
// Run from anywhere: node .claude/skills/verify-greet/smoke.mjs
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import assert from "node:assert/strict";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const bin = resolve(root, "bin/greet.js");

const cases = [
  { feature: "named greeting", args: ["Ada"], expect: "hello, Ada\n" },
  { feature: "default name", args: [], expect: "hello, world\n" },
  { feature: "help", args: ["--help"], expect: "usage: greet [name]\n" },
];

for (const c of cases) {
  const stdout = execFileSync(process.execPath, [bin, ...c.args], { encoding: "utf8" });
  assert.equal(stdout, c.expect, `${c.feature}: unexpected stdout`);
  console.log(`PASS ${c.feature}: exit 0, stdout ${JSON.stringify(stdout)}`);
}
console.log(`verify-greet: ${cases.length}/${cases.length} features observed`);

